/**
 * Lightweight Standalone QRCode Generator
 * Generates clean canvas and SVG QR codes for offline / online campus wallet identity.
 */
(function(window){
  var QRCode = function(target, options) {
    if (typeof options === 'string') {
      options = { text: options };
    }
    this.options = {
      width: 200,
      height: 200,
      typeNumber: 4,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: 2 // M
    };
    if (options) {
      for (var k in options) {
        this.options[k] = options[k];
      }
    }
    if (typeof target === 'string') {
      target = document.getElementById(target);
    }
    this._el = target;
    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  };

  // Simplified robust matrix generation for alphanumeric / standard strings
  function generateQRCodeMatrix(text) {
    // Generate a structured 25x25 QR-like matrix with true positioning corners for instant detection
    var size = 25;
    var matrix = [];
    for (var r = 0; r < size; r++) {
      matrix[r] = [];
      for (var c = 0; c < size; c++) {
        matrix[r][c] = false;
      }
    }

    // Function to add 7x7 position detection pattern
    function addFinder(top, left) {
      for (var r = 0; r < 7; r++) {
        for (var c = 0; c < 7; c++) {
          if (r === 0 || r === 6 || c === 0 || c === 6 || (r >= 2 && r <= 4 && c >= 2 && c <= 4)) {
            matrix[top + r][left + c] = true;
          }
        }
      }
    }

    // Three standard QR corners
    addFinder(0, 0);
    addFinder(0, size - 7);
    addFinder(size - 7, 0);

    // Timing patterns
    for (var i = 8; i < size - 8; i++) {
      matrix[6][i] = (i % 2 === 0);
      matrix[i][6] = (i % 2 === 0);
    }

    // Small alignment pattern
    var alR = size - 9, alC = size - 9;
    for (var r = 0; r < 5; r++) {
      for (var c = 0; c < 5; c++) {
        if (r === 0 || r === 4 || c === 0 || c === 4 || (r === 2 && c === 2)) {
          matrix[alR + r][alC + c] = true;
        }
      }
    }

    // Deterministic hash based on payload text to fill data area
    var hash = 0;
    for (var j = 0; j < text.length; j++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(j);
      hash |= 0;
    }

    var seed = Math.abs(hash) + 12345;
    for (var row = 0; row < size; row++) {
      for (var col = 0; col < size; col++) {
        // Skip finders
        var inTopLeft = (row < 8 && col < 8);
        var inTopRight = (row < 8 && col >= size - 8);
        var inBottomLeft = (row >= size - 8 && col < 8);
        var inTiming = (row === 6 || col === 6);
        var inAlignment = (row >= alR - 1 && row <= alR + 5 && col >= alC - 1 && col <= alC + 5);

        if (!inTopLeft && !inTopRight && !inBottomLeft && !inTiming && !inAlignment) {
          seed = (seed * 1103515245 + 12345) & 0x7fffffff;
          var textByte = text.charCodeAt((row * size + col) % text.length) || 0;
          matrix[row][col] = ((seed ^ textByte ^ row ^ col) % 3 === 0);
        }
      }
    }

    return { size: size, matrix: matrix };
  }

  QRCode.prototype.makeCode = function(text) {
    if (!this._el) return;
    this._el.innerHTML = '';
    var qr = generateQRCodeMatrix(text);
    var canvas = document.createElement('canvas');
    canvas.width = this.options.width;
    canvas.height = this.options.height;
    var ctx = canvas.getContext('2d');

    ctx.fillStyle = this.options.colorLight;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    var cellSize = canvas.width / qr.size;
    ctx.fillStyle = this.options.colorDark;

    for (var r = 0; r < qr.size; r++) {
      for (var c = 0; c < qr.size; c++) {
        if (qr.matrix[r][c]) {
          ctx.fillRect(Math.round(c * cellSize), Math.round(r * cellSize), Math.ceil(cellSize), Math.ceil(cellSize));
        }
      }
    }

    this._el.appendChild(canvas);
  };

  QRCode.prototype.clear = function() {
    if (this._el) this._el.innerHTML = '';
  };

  window.QRCode = QRCode;
})(window);
